}

.page-wrapper {
  width: 100%;
  max-width: 480px;
}

.form-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

/* Header */
.form-header {
  margin-bottom: 2rem;
  text-align: center;
}

.form-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.form-header p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Fields */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.required {
  color: var(--required);
  font-size: 0.8125rem;
}

.optional {
  color: var(--text-muted);
  font-size: 0.75rem;
  font-weight: 400;
}

input {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.9375rem;
  padding: 0.625rem 0.875rem;
  width: 100%;
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
  font-family: inherit;
}

input::placeholder {
  color: var(--text-muted);
}

input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(79, 124, 255, 0.18);
}

input.is-invalid {
  border-color: var(--error);
  box-shadow: 0 0 0 3px rgba(240, 92, 92, 0.15);
}

input.is-valid {
  border-color: var(--success);
}

/* Helper & error text */
.helper-text {
  font-size: 0.8125rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.error-message {
  font-size: 0.8125rem;
  color: var(--error);
  min-height: 1rem;
  line-height: 1.4;
}

/* Submit button */
.submit-btn {
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.75rem 1rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  font-family: inherit;
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--accent-hover);
  box-shadow: 0 4px 16px rgba(79, 124, 255, 0.35);
}

.submit-btn:active {
  transform: translateY(1px);
}

.submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* Success message */
.success-message {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: rgba(62, 207, 142, 0.1);
  border: 1px solid rgba(62, 207, 142, 0.3);
  border-radius: var(--radius);
  padding: 1rem;
  margin-top: 1.25rem;
  color: var(--success);
}

.success-message svg {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}

.success-message p {
  font-size: 0.9375rem;
  font-weight: 500;
}

@media (max-width: 480px) {
  .form-card {
    padding: 2rem 1.25rem;
  }
}
