  const form = document.getElementById('contactForm');
  const successMessage = document.getElementById('successMessage');

  const fields = {
    fullName: {
      el: document.getElementById('fullName'),
      required: true,
      validate(value) {
        if (!value) return 'Full name is required.';
        if (value.length < 2) return 'Please enter your full name.';
        return null;
      },
    },
    email: {
      el: document.getElementById('email'),
      required: true,
      validate(value) {
        if (!value) return 'Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return 'Please enter a valid email address.';
        return null;
      },
    },
    phone: {
      el: document.getElementById('phone'),
      required: false,
      validate(value) {
        if (!value) return null; // optional
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value)) return 'Please enter a valid phone number.';
        return null;
      },
    },
  };

  function getErrorEl(input) {
    return input.parentElement.querySelector('.error-message');
  }

  function showError(fieldKey, message) {
    const { el } = fields[fieldKey];
    const errorEl = getErrorEl(el);
    el.classList.add('is-invalid');
    el.classList.remove('is-valid');
    if (errorEl) errorEl.textContent = message;
  }

  function clearError(fieldKey) {
    const { el } = fields[fieldKey];
    const errorEl = getErrorEl(el);
    el.classList.remove('is-invalid');
    if (errorEl) errorEl.textContent = '';
  }

  function markValid(fieldKey) {
    const { el } = fields[fieldKey];
    el.classList.remove('is-invalid');
    el.classList.add('is-valid');
  }

  // Validate a single field; returns true if valid.
  function validateField(fieldKey) {
    const field = fields[fieldKey];
    const value = field.el.value.trim();
    const error = field.validate(value);
    if (error) {
      showError(fieldKey, error);
      return false;
    }
    clearError(fieldKey);
    if (value) markValid(fieldKey); // only mark green when there's content
    return true;
  }

  // Attach blur listeners so validation runs after the user leaves a field.
  Object.keys(fields).forEach((key) => {
    fields[key].el.addEventListener('blur', () => validateField(key));
    // Re-validate on input to clear errors eagerly once the user fixes them.
    fields[key].el.addEventListener('input', () => {
      if (fields[key].el.classList.contains('is-invalid')) {
        validateField(key);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const allValid = Object.keys(fields).map(validateField).every(Boolean);
    if (!allValid) return;

    // Simulate form submission.
    const btn = form.querySelector('.submit-btn');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      form.reset();
      Object.keys(fields).forEach((key) => {
        fields[key].el.classList.remove('is-valid', 'is-invalid');
      });
      btn.disabled = false;
      btn.textContent = 'Send Message';
      successMessage.hidden = false;
      successMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 800);
  });
})();
